package com.example

/**
 * Curated, 100% syllabus-accurate, non-repeating Flashcard Data
 * for History, Civics, Geography & Buddhism across 15 distinct sets (20 cards per set = 300 cards).
 */
object FlashcardSetsHistorySocial {

  fun getHistoryCard(setNum: Int, cardNum: Int, grade: String, theme: String): CardContentTuple {
    return when (setNum) {
      1 -> getHistorySet1(cardNum) // ඓතිහාසික මූලාශ්‍ර සහ ප්‍රාග් ඓතිහාසික යුගය
      2 -> getHistorySet2(cardNum) // අනුරාධපුර යුගයේ ආරම්භය & පණ්ඩුකාභය රජු
      3 -> getHistorySet3(cardNum) // මහින්දාගමනය & දේවානම්පියතිස්ස රජු
      4 -> getHistorySet4(cardNum) // දුටුගැමුණු රජු & එක්සේසත් කිරීම
      5 -> getHistorySet5(cardNum) // වළගම්බා රජු & ත්‍රිපිටකය ග්‍රන්ථාරූඪ කිරීම
      6 -> getHistorySet6(cardNum) // වාරි ශිෂ්ටාචාරය (වසභ, මහසෙන්, ධාතුසේන)
      7 -> getHistorySet7(cardNum) // පොළොන්නරු යුගය (1 වන විජයබාහු & මහා පරාක්‍රමබාහු)
      8 -> getHistorySet8(cardNum) // දඹදෙණි, යාපහුව, කුරුණෑගල & ගම්පොළ යුග
      9 -> getHistorySet9(cardNum) // කෝට්ටේ සහ සීතාවක රාජධානි
      10 -> getHistorySet10(cardNum) // උඩරට රාජධානිය (1 වන විමලධර්මසූරිය & 2 වන රාජසිංහ)
      11 -> getHistorySet11(cardNum) // පෘතුගීසි & ලන්දේසි පාලනය
      12 -> getHistorySet12(cardNum) // බ්‍රිතාන්‍ය පාලනය & 1815 උඩරට ගිවිසුම
      13 -> getHistorySet13(cardNum) // 1818 ඌව වෙල්ලස්ස & 1848 මාතලේ නිදහස් අරගල
      14 -> getHistorySet14(cardNum) // ආණ්ඩුක්‍රම ප්‍රතිසංස්කරණ (කෝල්බෲක්, ඩොනමෝර්, සෝල්බරි) & 1948 නිදහස
      15 -> getHistorySet15(cardNum) // ලෝක ඉතිහාසය (කාර්මික විප්ලවය, ලෝක යුද්ධ, එක්සත් ජාතීන්)
      else -> getHistorySet1(cardNum)
    }
  }

  fun getCivicsCard(setNum: Int, cardNum: Int, grade: String, theme: String): CardContentTuple {
    return when (setNum) {
      1 -> getCivicsSet1(cardNum) // ප්‍රජාතන්ත්‍රවාදය & මූලික ලක්ෂණ
      2 -> getCivicsSet2(cardNum) // ආණ්ඩුක්‍රම ව්‍යවස්ථාව & නීතියේ ආධිපත්‍යය
      3 -> getCivicsSet3(cardNum) // ව්‍යවස්ථාදායකය (පාර්ලිමේන්තුව)
      4 -> getCivicsSet4(cardNum) // විධායකය (ජනාධිපති & අමාත්‍ය මණ්ඩලය)
      5 -> getCivicsSet5(cardNum) // අධිකරණය & ස්වාධීනත්වය
      6 -> getCivicsSet6(cardNum) // මූලික මිනිස් අයිතිවාසිකම්
      7 -> getCivicsSet7(cardNum) // පළාත් පාලන ආයතන & මහජන සේවය
      8 -> getCivicsSet8(cardNum) // යහපාලනය & විනිවිදභාවය
      9 -> getCivicsSet9(cardNum) // බහු-සංස්කෘතික සමාජය & සහජීවනය
      10 -> getCivicsSet10(cardNum) // ගැටුම් නිරාකරණය & සාමය
      11 -> getCivicsSet11(cardNum) // ඡන්ද බලය & මැතිවරණ ක්‍රමය
      12 -> getCivicsSet12(cardNum) // මහජන මතය & මාධ්‍ය නිදහස
      13 -> getCivicsSet13(cardNum) // තිරසාර සංවර්ධනය & පරිසර නීති
      14 -> getCivicsSet14(cardNum) // එක්සත් ජාතීන්ගේ සංවිධානය & ජාත්‍යන්තරය
      15 -> getCivicsSet15(cardNum) // පුරවැසි වගකීම් & ක්‍රියාකාරී සහභාගිත්වය
      else -> getCivicsSet1(cardNum)
    }
  }

  fun getBuddhismCard(setNum: Int, cardNum: Int, grade: String, theme: String): CardContentTuple {
    return when (setNum) {
      1 -> getBuddhismSet1(cardNum) // බුද්ධ චරිතය & බෝධිසත්ව ගුණ
      2 -> getBuddhismSet2(cardNum) // ප්‍රථම ධර්ම දේශනාව & චතුරාර්ය සත්‍යය
      3 -> getBuddhismSet3(cardNum) // ආර්ය අෂ්ටාංගික මාර්ගය & ත්‍රිශික්ෂාව
      4 -> getBuddhismSet4(cardNum) // ත්‍රිලක්ෂණය (අනිච්ච, දුක්ඛ, අනත්ත)
      5 -> getBuddhismSet5(cardNum) // පටිච්චසමුප්පාදය & කර්ම න්‍යාය
      6 -> getBuddhismSet6(cardNum) // පංචශීලය & බෞද්ධ ආචාර ධර්ම
      7 -> getBuddhismSet7(cardNum) // මංගල, පරාභව & වසල සූත්‍ර
      8 -> getBuddhismSet8(cardNum) // ප්‍රථම ධර්ම සංගායනාව
      9 -> getBuddhismSet9(cardNum) // දෙවන & තෙවන ධර්ම සංගායනා
      10 -> getBuddhismSet10(cardNum) // මහින්දාගමනය & ලක්දිව ශාසන පිහිටුවීම
      11 -> getBuddhismSet11(cardNum) // සංඝමිත්තා තෙරණිය & ශ්‍රී මහා බෝධිය
      12 -> getBuddhismSet12(cardNum) // ත්‍රිපිටකය ග්‍රන්ථාරූඪ කිරීම (මාතලේ අලුවිහාරය)
      13 -> getBuddhismSet13(cardNum) // බෞද්ධ සංස්කෘතිය & වෙහෙර විහාර
      14 -> getBuddhismSet14(cardNum) // භාවනාව & චිත්ත සමාධිය (සමථ, විදර්ශනා)
      15 -> getBuddhismSet15(cardNum) // බෞද්ධ ආර්ථික දර්ශනය & සමාජ දර්ශනය
      else -> getBuddhismSet1(cardNum)
    }
  }

  fun getGeographyCard(setNum: Int, cardNum: Int, grade: String, theme: String): CardContentTuple {
    return when (setNum) {
      1 -> getGeographySet1(cardNum) // පෘථිවියේ අභ්‍යන්තර ව්‍යුහය & භූ තල චලන
      2 -> getGeographySet2(cardNum) // ශ්‍රී ලංකාවේ භූ විෂමතාව (තලා 3)
      3 -> getGeographySet3(cardNum) // ශ්‍රී ලංකාවේ ගංගා පද්ධතිය & ද්‍රෝණි
      4 -> getGeographySet4(cardNum) // මෝසම් සුළං & දේශගුණ කලාප
      5 -> getGeographySet5(cardNum) // 1:50,000 භූ ලක්ෂණ සිතියම් කියවීම
      6 -> getGeographySet6(cardNum) // ස්වභාවික වෘක්ෂලතා & පස් වර්ග
      7 -> getGeographySet7(cardNum) // වී වගාව & ප්‍රධාන වැවිලි බෝග (තේ, රබර්, පොල්)
      8 -> getGeographySet8(cardNum) // ඛනිජ සම්පත් & බලශක්ති ප්‍රභව
      9 -> getGeographySet9(cardNum) // ධීවර කර්මාන්තය & සාගර සම්පත්
      10 -> getGeographySet10(cardNum) // ජනගහන වර්ධනය, ව්‍යාප්තිය & ඝනත්වය
      11 -> getGeographySet11(cardNum) // ජනාවාස රටා (ග්‍රාමීය & නාගරික)
      12 -> getGeographySet12(cardNum) // පරිසර දූෂණය & ස්වාභාවික ආපදා
      13 -> getGeographySet13(cardNum) // ගෝලීය උණුසුම & හරිතාගාර ආචරණය
      14 -> getGeographySet14(cardNum) // ප්‍රවාහනය & සන්නිවේදනය
      15 -> getGeographySet15(cardNum) // ලෝක දේශගුණ කලාප & සම්පත්
      else -> getGeographySet1(cardNum)
    }
  }

  // --- HISTORY SET 1: ඓතිහාසික මූලාශ්‍ර & ප්‍රාග් ඓතිහාසික යුගය ---
  private fun getHistorySet1(c: Int): CardContentTuple {
    val items = listOf(
      CardContentTuple("ශ්‍රී ලංකා ඉතිහාසය හැදෑරීමේ ප්‍රධාන සාහිත්‍ය මූලාශ්‍ර 2 මොනවාද?", "දීපවංශය (පැරණිතම වංශකථාව) සහ මහාවංශය (මහානාම හිමියන් විසින් රචිත).", "චූලවංශය මගින් මහාවංශයේ පසුකාලීන කොටස් ආවරණය කරයි.", "දීපවංශය & මහාවංශය"),
      CardContentTuple("පුරාවිද්‍යාත්මක මූලාශ්‍ර වර්ග 3 මොනවාද?", "1. සෙල්ලිපි (ශිලාලේඛන) 2. කාසි 3. නටබුන් සහ ස්මාරක.", "සෙල්ලිපි කිසිවෙකුගේ සංස්කරණයට ලක් නොවූ සමකාලීන ප්‍රාථමික මූලාශ්‍ර වේ.", "සෙල්ලිපි, කාසි, නටබුන්"),
      CardContentTuple("ලක්දිව පැරණිතම සෙල්ලිපි ලියා ඇති අක්ෂර හා භාෂාව කුමක්ද?", "ප්‍රාකෘත භාෂාවෙන් සහ පූර්ව බ්‍රාහ්මී අක්ෂරවලින්.", "ක්‍රි.පූ. 3 වන සියවසේ සිට ලෙන් ලිපි බහුලව හමුවේ.", "පූර්ව බ්‍රාහ්මී & ප්‍රාකෘත"),
